/* Planners share the same save, canvas, export and writing companion controls as notes. */
(function(){'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],P=()=>window.NotaPlanning;
function budget(n,c){const b=n.budget;
 NotaModeEditors.shell(n,c,'Budget planner',`<p class="mode-lead">A little room in your budget.</p><p class="hint">Plan where your money goes, then compare it with what happened. Blank amounts count as zero. Use a decimal point; no commas.</p><div class="planner-settings"><label>Budget period<input id="budget-month" type="month" min="1900-01" max="2199-12" value="${b.month}"></label><label>Currency<select id="budget-currency">${P().currencies.map(x=>`<option ${x===b.currency?'selected':''}>${x}</option>`).join('')}</select></label><label>Set aside<input id="budget-reserve" inputmode="decimal" maxlength="24" value="${c.esc(b.reserve)}" placeholder="0.00"></label></div><p class="hint">Set aside protects an amount before calculating your room to spend. Changing currency relabels amounts; it does not convert them.</p><section id="budget-summary" class="budget-summary" aria-live="polite"></section><p id="budget-errors" class="planner-error" role="status"></p><div id="budget-rows"></div><div class="planner-actions"><button class="secondary" id="budget-add-income"><i data-lucide="plus"></i> Income</button><button class="secondary" id="budget-add-expense"><i data-lucide="plus"></i> Expense</button></div><p class="hint">This plan stays in this note. It does not connect to a bank. Actual totals reflect only the amounts you enter.</p>`);
 const persist=NotaModeEditors.common(n,c,()=>P().budgetHTML(b));
 const results=()=>{const t=P().budgetTotals(b),money=v=>c.esc(P().money(v,b.currency));$('#budget-errors').textContent=t.errors.length?'Finish the marked amounts to see accurate totals.':'';$('#budget-reserve').setAttribute('aria-invalid',String(t.errors.some(e=>e.id==='reserve')));
 $('#budget-summary').innerHTML=t.errors.length?'<p>Totals are paused while an amount needs attention.</p>':`<div><span>Planned room to spend</span><strong class="${t.plannedLeft<0?'planner-negative':''}">${money(t.plannedLeft)}</strong></div><div><span>Actual room to spend</span><strong class="${t.actualLeft<0?'planner-negative':''}">${money(t.actualLeft)}</strong></div><p>Actual income ${money(t.actualIncome)} · Expenses ${money(t.actualExpense)} · Set aside ${money(t.reserve)}</p>`;
 for(const row of b.rows){const errors=t.errors.filter(e=>e.id===row.id);const output=$(`[data-budget-result="${row.id}"]`);for(const el of $$(`[data-budget-id="${row.id}"][data-budget-field]`))el.setAttribute('aria-invalid',String(errors.some(e=>e.field===el.dataset.budgetField)));if(errors.length){output.textContent='Check '+errors.map(e=>e.field).join(' and ')+': use up to two decimal places.';continue;}const planned=P().amount(row.planned),actual=P().amount(row.actual),difference=row.kind==='expense'?planned-actual:actual-planned;output.innerHTML=row.kind==='expense'?`<div class="budget-track" role="img" aria-label="${c.esc(row.label)}: ${money(actual)} spent of ${money(planned)} planned"><span style="width:${planned?Math.min(100,actual/planned*100):actual?100:0}%" class="${difference<0?'over':''}"></span></div><span>${money(Math.abs(difference))} ${difference<0?'over plan':'left in this category'}</span>`:`<span>${money(Math.abs(difference))} ${difference<0?'below':'above'} planned income</span>`;}
 persist();};
 const render=()=>{$('#budget-rows').innerHTML=b.rows.map((r,i)=>`<section class="budget-row"><header><span>${r.kind==='income'?'Coming in':'Going out'}</span><button class="icon-button" data-budget-remove="${r.id}" aria-label="Remove budget category ${i+1}" ${b.rows.length===1?'disabled':''}><i data-lucide="trash-2"></i></button></header><label>Category<input data-budget-field="label" data-budget-id="${r.id}" value="${c.esc(r.label)}" maxlength="100" placeholder="What is this for?"></label><div class="budget-amounts">${['planned','actual'].map(k=>`<label>${k==='planned'?'Planned':'Actual'}<input inputmode="decimal" data-budget-id="${r.id}" data-budget-field="${k}" value="${c.esc(r[k])}" maxlength="24" placeholder="0.00"></label>`).join('')}</div><div data-budget-result="${r.id}" class="budget-row-result"></div></section>`).join('');$$('[data-budget-field]').forEach(el=>el.oninput=()=>{b.rows.find(r=>r.id===el.dataset.budgetId)[el.dataset.budgetField]=el.value;results();});$$('[data-budget-remove]').forEach(el=>el.onclick=()=>{if(b.rows.length===1)return;const row=b.rows.find(r=>r.id===el.dataset.budgetRemove);if(!confirm(`Remove “${row.label||'this category'}” and its amounts?`))return;b.rows=b.rows.filter(r=>r!==row);render();});for(const k of ['income','expense'])$('#budget-add-'+k).disabled=b.rows.length>=80;results();c.icons();};
 for(const kind of ['income','expense'])$('#budget-add-'+kind).onclick=()=>{if(b.rows.length>=80)return;const row={id:c.uid(),kind,label:'',planned:'',actual:''};b.rows.push(row);render();$(`[data-budget-id="${row.id}"][data-budget-field=label]`).focus();};$('#budget-reserve').oninput=()=>{b.reserve=$('#budget-reserve').value;results();};$('#budget-currency').onchange=()=>{b.currency=$('#budget-currency').value;results();};$('#budget-month').onchange=()=>{const value=$('#budget-month').value;if(!P().validMonth(value)){$('#budget-month').value=b.month;c.toast('Choose a month between 1900 and 2199.');return;}b.month=value;persist();};render();
}
function calendar(n,c){const cal=n.calendar;const today=P().localDate(new Date()),dateLabel=date=>new Date(date+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',year:'numeric',month:'long',day:'numeric'});
 NotaModeEditors.shell(n,c,'Calendar',`<p class="mode-lead">Make room for what is coming.</p><p class="hint">Choose a day for plans, small reminders, or thoughts to return to. Dates written in this editor can be added using Remember in the date suggestions. Entries save as you type.</p><div class="calendar-toolbar"><button id="calendar-prev" aria-label="Previous month"><i data-lucide="chevron-left"></i></button><h3 id="calendar-month" aria-live="polite"></h3><button id="calendar-next" aria-label="Next month"><i data-lucide="chevron-right"></i></button><button id="calendar-today" class="secondary">Today</button></div><div class="calendar-weekdays" aria-hidden="true">${Array.from({length:7},(_,i)=>`<span>${new Date(2026,9,18+i,12).toLocaleDateString(undefined,{weekday:'short'})}</span>`).join('')}</div><div id="calendar-days" class="calendar-days" role="group" aria-labelledby="calendar-month"></div><section class="calendar-agenda"><h3 id="calendar-day-title"></h3><div class="planner-actions"><button id="calendar-add" class="secondary"><i data-lucide="plus"></i> Add a plan</button><button id="calendar-journal" class="secondary"><i data-lucide="book-open-text"></i> Journal for this day</button></div><div id="calendar-entries"></div></section><p class="hint">This calendar lives in your note. It does not sync with your phone calendar. Make an entry a task, then use its bell to choose notifications.</p>`);
 const persist=NotaModeEditors.common(n,c,()=>P().calendarHTML(cal));
 const renderMonth=()=>{$('#calendar-month').textContent=new Date(cal.month+'-01T12:00:00').toLocaleDateString(undefined,{month:'long',year:'numeric'});$('#calendar-prev').disabled=!P().shiftMonth(cal.month,-1);$('#calendar-next').disabled=!P().shiftMonth(cal.month,1);$('#calendar-days').innerHTML=P().monthDays(cal.month).map(date=>{const count=cal.events.filter(e=>e.date===date).length;return `<button data-calendar-date="${date}" class="${date.slice(0,7)!==cal.month?'outside':''}" aria-pressed="${date===cal.selected}" ${date===today?'aria-current="date"':''} aria-label="${c.esc(dateLabel(date))}${count?' · '+count+' entries':''}" ${P().validDate(date)?'':'disabled'}><span>${Number(date.slice(-2))}</span>${count?'<small>'+count+'</small>':''}</button>`;}).join('');$$('[data-calendar-date]').forEach(el=>{el.onclick=()=>select(el.dataset.calendarDate);el.onkeydown=e=>{const offset={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[e.key];if(offset===undefined)return;e.preventDefault();const date=P().shiftDate(el.dataset.calendarDate,offset);if(date){select(date);$(`[data-calendar-date="${date}"]`)?.focus();}};});};
 const select=date=>{cal.selected=date;cal.month=date.slice(0,7);render();persist();};
 const render=()=>{renderMonth();$('#calendar-day-title').textContent=dateLabel(cal.selected);$('#calendar-add').disabled=cal.events.length>=300;const entries=P().dayEntries(cal,cal.selected);$('#calendar-entries').innerHTML=entries.length?entries.map(e=>`<section class="calendar-entry" data-calendar-entry="${e.id}"><header><span>${c.esc(e.time||'All day')}</span><button data-event-remove="${e.id}" class="icon-button" aria-label="Remove ${c.esc(e.title||'this plan')}"><i data-lucide="trash-2"></i></button></header><label>Plan<input data-event-id="${e.id}" data-event-field="title" value="${c.esc(e.title)}" maxlength="160" placeholder="What would you like to make time for?"></label><div class="planner-settings"><label>Date<input type="date" data-event-id="${e.id}" data-event-field="date" value="${e.date}" min="1900-01-01" max="2199-12-31"></label><label>Time (optional)<input type="time" data-event-id="${e.id}" data-event-field="time" value="${e.time}"></label></div><label>Details<textarea data-event-id="${e.id}" data-event-field="body" maxlength="4000" rows="3" placeholder="A place, a thought, or the next step…">${c.esc(e.body)}</textarea></label><button class="secondary" data-event-task="${e.id}" ${e.title.trim()?'':'disabled'}><i data-lucide="list-todo"></i> ${e.taskId?'Open task':'Make it a task'}</button></section>`).join(''):'<p class="hint calendar-empty">A little room in this day. Add a plan or open its journal.</p>';
 $$('[data-event-field]').forEach(el=>{const event=cal.events.find(e=>e.id===el.dataset.eventId),key=el.dataset.eventField;const update=()=>{if(key==='date'&&!P().validDate(el.value)){el.value=event.date;c.toast('Choose a valid date.');return;}if(key==='time'&&el.value&&!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(el.value)){el.value=event.time;return;}event[key]=el.value;if(key==='date'){select(event.date);return;}if(key==='title')$(`[data-event-task="${event.id}"]`).disabled=!event.title.trim();if(key==='time')$(`[data-calendar-entry="${event.id}"] header>span`).textContent=event.time||'All day';persist();};if(['date','time'].includes(key))el.onchange=update;else el.oninput=update;});
 $$('[data-event-remove]').forEach(el=>el.onclick=()=>{const event=cal.events.find(e=>e.id===el.dataset.eventRemove);if(!confirm(`Remove “${event.title||'this plan'}” from this calendar? Any task already made from it is kept.`))return;cal.events=cal.events.filter(e=>e!==event);render();persist();});$$('[data-event-task]').forEach(el=>el.onclick=()=>{const event=cal.events.find(e=>e.id===el.dataset.eventTask);persist();c.promote({id:event.taskId,title:event.title,text:event.date+(event.time?' · '+event.time:' · All day')+(event.body?'\n'+event.body:''),task:true,parent:n,onId:id=>event.taskId=id});});c.icons();};
 $('#calendar-prev').onclick=()=>{const month=P().shiftMonth(cal.month,-1);if(month)select(month+'-01');};$('#calendar-next').onclick=()=>{const month=P().shiftMonth(cal.month,1);if(month)select(month+'-01');};$('#calendar-today').onclick=()=>select(today);$('#calendar-add').onclick=()=>{if(cal.events.length>=300)return;const e={id:c.uid(),date:cal.selected,time:'',title:'',body:''};cal.events.push(e);render();persist();$(`[data-event-id="${e.id}"][data-event-field=title]`).focus();};$('#calendar-journal').onclick=()=>{persist();c.openJournal(cal.selected);};render();c.icons();
}
window.NotaPlanningEditors={budget,calendar};
})();
